update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/lyon/valence/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"La maintenance industrielle à Valence et dans la Drôme","mecanisme":"Dans la Drôme, l''industrie vit au rythme des campagnes : les fruits arrivent, les lignes d''embouteillage et de conditionnement de la plaine tournent à plein, et tout se joue sur quelques semaines. Autour, l''axe rhodanien aligne les plateformes logistiques, Rovaltain la mécanique de précision, Romans le cuir, le sud du département l''énergie. Nous préparons vos équipements avant le pic, pas pendant.","cta":"Faire chiffrer ma maintenance à Valence","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon siège du groupe, Montréal, Dubaï et Madrid","detail":"Aucune dans la Drôme, des techniciens qui s''y déplacent"}]},{"type":"probleme","punchline":"Une ligne d''embouteillage à l''arrêt en pleine campagne, et le seul technicien qui connaît la machine est en congé. La saison ne se décale pas, elle se perd.","puces":[{"accroche":"La saison concentre l''année sur quelques semaines.","texte":"Fruits, jus, conditionnement : ce qui n''est pas produit pendant le pic ne se rattrape pas au trimestre suivant."},{"accroche":"Le préventif saute toujours au pire moment.","texte":"Les visites planifiées passent après la production, jusqu''au jour où le correctif explose le budget."},{"accroche":"Une compétence unique est un risque unique.","texte":"Un congé, un arrêt maladie, un départ, et le site devient aveugle sur ses propres machines."},{"accroche":"L''axe rhodanien travaille quand les camions partent.","texte":"Convoyeurs, trieurs, quais des plateformes de la vallée : les fenêtres d''intervention sont nocturnes."},{"accroche":"Le sud du département n''a aucune marge.","texte":"Énergie, traitement de l''eau, valorisation des déchets : des installations au service du public, tenues par les vérifications légales."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Un compte à rebours avant la campagne","texte":"préventif resserré, pièces d''usure remplacées, points critiques repris avant le démarrage."},"benefice":"Vous entrez en saison avec un parc prêt, pas avec une liste de réparations en attente."},{"prestation":{"accroche":"Un renfort pendant le pic","texte":", en appui de vos équipes, sans embauche précipitée."},"benefice":"La cadence tient sans épuiser l''équipe interne ni empiler les heures supplémentaires."},{"prestation":{"accroche":"Des gammes adaptées au lavage et au froid","texte":"étanchéité, protection des moteurs, éléments d''usure suivis."},"benefice":"Vos lignes agroalimentaires cessent de subir les mêmes réparations chaque année."},{"prestation":{"accroche":"Des interventions en heures creuses","texte":", tôt le matin, entre deux équipes, de nuit."},"benefice":"Les opérations lourdes ne mangent jamais une rotation de quai sur l''axe rhodanien."},{"prestation":{"accroche":"Le champ technique complet","texte":"[mécanique](/expertises/mecanique/), [électricité](/expertises/electrique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/)."},"benefice":"Un seul contrat pour un parc qui mélange embouteillage, extrusion et convoyage."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", tenue par nos techniciens mobiles, comme partout en France ([voir nos implantations](/implantations/lyon/))."},"benefice":"Une panne de nuit en pleine campagne ne coûte plus une journée de production."}]},{"type":"deroule","etapes":[{"titre":"L''appel qualifié","texte":"Vous exposez la situation au 04 78 33 72 05. Rappel dans l''heure aux horaires ouvrés : équipement concerné, accès, habilitations, urgence réelle."},{"titre":"Le devis","texte":"Périmètre, moyens, conditions et taux, écrits avant le départ. Tout écart de périmètre passe par un accord préalable."},{"titre":"L''état des lieux avant saison","texte":"Inventaire des points critiques, pièces d''usure, retard de préventif à résorber avant le démarrage de la campagne."},{"titre":"L''intervention","texte":"Accueil sécurité, consignation, diagnostic, réparation, essais, montée en cadence avec vos opérateurs."},{"titre":"La cause racine","texte":"L''analyse cherche l''origine de la défaillance pour qu''elle ne revienne pas au même point la saison suivante."},{"titre":"Le compte rendu","texte":"Actions, pièces, résultats, préconisations, versés dans votre GMAO. Les données restent chez vous."}]},{"type":"garanties","puces":[{"accroche":"La continuité, même en cas d''absence","texte":"congé, départ ou surcroît d''activité, le réseau fournit un profil équivalent briefé sur vos installations. Votre saison ne repose plus sur une seule personne."},{"accroche":"La sélection prouvée avant la saison","texte":"entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation remis avant que le renfort arrive."},{"accroche":"Tout écrit avant la première visite","texte":"équipements couverts, fréquences, indicateurs suivis, conditions de sortie. Aucun avenant découvert après coup."}]},{"type":"cta","question":"Besoin de préparer vos lignes avant la prochaine campagne plutôt que pendant ?","bouton":"Faire chiffrer ma maintenance à Valence","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/lyon/valence/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Deux techniciens Migen postés en 3x8 sur des lignes liquides et poudre","texte":", site agroalimentaire","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Techniciens en renfort sur un site agroalimentaire, premier contrat hors de France depuis octobre 2024","lienLibelle":"Étude de cas McCAIN : Belgique","lienHref":"/preuves/mccain-belgique/"},{"titre":"Un technicien capable de passer d''un équipement à l''autre sur un site papier et emballage","texte":"2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Un électromécanicien habilité risque chimique mobilisé 6 mois","texte":"remise en état d''un site de traitement des eaux industrielles","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Six techniciens en permanence sur un contrat de préventif annuel multi-sites","texte":"prise en charge complète réalisée en un mois","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"}]},{"type":"objections","questions":[{"question":"Pouvez-vous nous renforcer uniquement pendant la campagne ?","reponse":"Oui. Le renfort se dimensionne sur la durée du pic et les technologies en cause, en appui de vos équipes. Beaucoup de sites drômois combinent un préventif resserré avant la saison et une présence pendant, puis reviennent à un rythme normal. Le format et les dates s''écrivent au devis."},{"question":"Avez-vous une agence à Valence ?","reponse":"Non. Migen n''a ni agence ni hub de techniciens dans la Drôme. Nos quatre agences sont Lyon, siège du groupe, Montréal, Dubaï et Madrid. Ce que nous avons ici, ce sont des techniciens mobiles qui viennent sur votre site, et un chargé d''affaires qui connaît vos machines et vos accès."},{"question":"Couvrez-vous toute la Drôme ?","reponse":"Oui : Valence, Portes-lès-Valence, Bourg-lès-Valence, Chabeuil, Romans-sur-Isère, Montélimar et la vallée du Rhône. Nos techniciens se déplacent aussi vers Lyon, Grenoble, Saint-Étienne et la France entière, avec un contrat unique et des comptes rendus au même format."},{"question":"Quel délai pour une intervention à Valence ?","reponse":"Aucun chiffre d''affichage sur cette page. Nous tenons deux choses : le rappel dans l''heure aux horaires ouvrés et une qualification qui évite un aller-retour inutile. L''astreinte 24/24 et 7/7 couvre en option la nuit, le week-end et les jours fériés."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"Zéro arrêt est chiffré sur devis, avec trois niveaux de couverture et un engagement type de 6 mois renouvelable. Sur un site saisonnier, le contrat peut prévoir un préventif renforcé avant campagne et un rythme allégé le reste de l''année. Le diagnostic de départ est gratuit, le périmètre s''écrit après état des lieux."},{"question":"Pouvez-vous tenir un poste chez nous toute l''année ?","reponse":"Oui, avec l''offre [résidence](/offres/residence/) : un salarié Migen intégré à votre équipe et encadré par un référent, en poste sous 2 à 3 semaines. La même personne suit vos machines saison après saison, et le remplacement est assuré en cas d''absence."},{"question":"Faites-vous la maintenance CVC ou multitechnique de bâtiments ?","reponse":"Non. Le confort thermique et l''entretien de bâtiments tertiaires ne sont pas notre métier. Notre terrain est l''équipement de production industrielle : lignes, machines, convoyeurs et utilités de process, en préventif comme en curatif."}]},{"type":"ctaFinal","question":"Besoin de passer la campagne sans dépendre d''une seule personne ?","bouton":"Faire chiffrer ma maintenance à Valence","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/lyon/valence/';
